-- Add nullable column
ALTER TABLE orders ADD COLUMN public_id uuid;

-- Trigger function to populate public_id on insert
CREATE FUNCTION set_public_id() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.public_id IS NULL THEN
    NEW.public_id := gen_random_uuid();
  END IF;
  RETURN NEW;
END;
$$;

-- Allow app to execute the trigger function
GRANT EXECUTE ON FUNCTION set_public_id() TO app;

-- Attach trigger
CREATE TRIGGER orders_set_public_id
BEFORE INSERT ON orders
FOR EACH ROW EXECUTE FUNCTION set_public_id();

-- Procedure to backfill existing rows in batches
CREATE PROCEDURE backfill_public_id() LANGUAGE plpgsql AS $$
DECLARE
  batch_size BIGINT := 5000;
  max_id BIGINT;
  low BIGINT;
  high BIGINT;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  low := 1;
  WHILE low <= max_id LOOP
    high := low + batch_size - 1;
    UPDATE orders
    SET public_id = gen_random_uuid()
    WHERE public_id IS NULL
      AND id BETWEEN low AND high;
    COMMIT;
    low := high + 1;
  END LOOP;
END;
$$;

-- Execute backfill
CALL backfill_public_id();

-- Enforce NOT NULL and set default for future inserts
ALTER TABLE orders ALTER COLUMN public_id SET NOT NULL;
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

-- Clean up trigger and function
DROP TRIGGER orders_set_public_id ON orders;
DROP FUNCTION set_public_id();
```

